{"implementation": "def solve(case):
    # Validate required top-level fields
    if "nodes" not in case:
        raise ValueError("Missing 'nodes' field in case")
    if "required_symbols" not in case:
        raise ValueError("Missing 'required_symbols' field in case")

    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("'nodes' must be a non-empty list")

    # Validate each node has all required fields
    required_node_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    node_ids = set()
    for n in nodes:
        missing = required_node_fields - set(n.keys())
        if missing:
            raise ValueError(f"Node missing required fields: {missing}")
        if n["id"] in node_ids:
            raise ValueError(f"Duplicate node id: {n['id']}")
        node_ids.add(n["id"])

    # Validate parent references
    for n in nodes:
        if n["parent"] is not None and n["parent"] not in node_ids:
            raise ValueError(f"Node {n['id']} references unknown parent {n['parent']}")

    # Exactly one root (parent=null)
    roots = [n for n in nodes if n["parent"] is None]
    if len(roots) != 1:
        raise ValueError(f"Expected exactly one root node, found {len(roots)}")

    # Build children map (deterministic: sort children by id for consistent iteration)
    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        if n["parent"] is not None:
            children[n["parent"]].append(n["id"])
    for nid in children:
        children[nid].sort()

    # Processing order: deeper nodes first, tie-break by node ID ascending (lexicographic)
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    # retained tracks which nodes are still in the tree
    retained = {n["id"]: True for n in nodes}
    removed_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Hard constraint: not removable
        if not node["removable"]:
            continue

        # Hard constraint: node's own symbol is required
        if node["symbol"] in required_symbols:
            continue

        # Hard constraint: node has retained children
        if any(retained[cid] for cid in children[nid]):
            continue

        # Interestingness oracle: all required symbols must remain represented
        # after tentatively removing this node
        remaining_symbols = set()
        for n in nodes:
            if n["id"] != nid and retained[n["id"]]:
                remaining_symbols.add(n["symbol"])

        if not required_symbols.issubset(remaining_symbols):
            continue

        # All checks passed: remove this node
        retained[nid] = False
        removed_order.append(nid)

    retained_ids = sorted(nid for nid, r in retained.items() if r)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_ids
    }
"}
